package slop

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

// Embedded canonical analysis data, generated by tools/datagen from the
// pinned upstream revision recorded in manifest.json.
//
//go:embed data/slop_list.json
var slopListJSON []byte

//go:embed data/slop_list_bigrams.json
var slopBigramsJSON []byte

//go:embed data/slop_list_trigrams.json
var slopTrigramsJSON []byte

//go:embed data/calibration.json
var calibrationJSON []byte

//go:embed data/manifest.json
var manifestJSON []byte

// NormRange is a padded min/max calibration range from the leaderboard.
type NormRange struct {
	Min float64 `json:"min"`
	Max float64 `json:"max"`
}

type calibrationFile struct {
	Version int                  `json:"version"`
	Ranges  map[string]NormRange `json:"ranges"`
}

// Manifest records data provenance from the pinned upstream source.
type Manifest struct {
	Version int `json:"version"`
	Source  struct {
		Repo    string `json:"repo"`
		Commit  string `json:"commit"`
		License string `json:"license"`
	} `json:"source"`
	Files map[string]struct {
		SHA256  string `json:"sha256"`
		Bytes   int    `json:"bytes"`
		Entries int    `json:"entries,omitempty"`
	} `json:"files"`
	Leaderboard struct {
		SHA256                string `json:"sha256"`
		Bytes                 int    `json:"bytes"`
		Results               int    `json:"results"`
		IncludesHumanBaseline bool   `json:"includes_human_baseline"`
	} `json:"leaderboard"`
}

// Data is the loaded, ready-to-match analysis data.
type Data struct {
	Words    map[string]struct{}
	Bigrams  map[string]struct{}
	Trigrams map[string]struct{}

	WordRange     NormRange
	TrigramRange  NormRange
	ContrastRange NormRange

	Manifest Manifest
}

// entryPhrase mirrors the pinned upstream loadSlopSets normalization
// (post commit 289264a): lowercase the entry, then take the first match of
// /[a-z]+(?:'[a-z]+)?(?:\s+[a-z]+(?:'[a-z]+)?)*/ so punctuation and stray
// characters cannot corrupt a list entry.
var entryPhraseRe = regexp.MustCompile(`[a-z]+(?:'[a-z]+)?(?:\s+[a-z]+(?:'[a-z]+)?)*`)

func loadList(raw []byte, name string) (map[string]struct{}, error) {
	var entries [][]string
	if err := json.Unmarshal(raw, &entries); err != nil {
		return nil, fmt.Errorf("parse %s: %w", name, err)
	}
	if len(entries) == 0 {
		return nil, fmt.Errorf("%s is empty", name)
	}
	set := make(map[string]struct{}, len(entries))
	for i, e := range entries {
		if len(e) == 0 || e[0] == "" {
			return nil, fmt.Errorf("%s entry %d has no phrase", name, i)
		}
		phrase := entryPhraseRe.FindString(strings.ToLower(e[0]))
		if phrase == "" {
			return nil, fmt.Errorf("%s entry %d (%q) yields no phrase", name, i, e[0])
		}
		set[phrase] = struct{}{}
	}
	return set, nil
}

// LoadData parses the embedded lists and calibration ranges.
func LoadData() (*Data, error) {
	words, err := loadList(slopListJSON, "slop_list.json")
	if err != nil {
		return nil, err
	}
	bigrams, err := loadList(slopBigramsJSON, "slop_list_bigrams.json")
	if err != nil {
		return nil, err
	}
	trigrams, err := loadList(slopTrigramsJSON, "slop_list_trigrams.json")
	if err != nil {
		return nil, err
	}

	var cal calibrationFile
	if err := json.Unmarshal(calibrationJSON, &cal); err != nil {
		return nil, fmt.Errorf("parse calibration.json: %w", err)
	}
	for _, key := range []string{"slop_words", "slop_trigrams", "contrast_patterns"} {
		r, ok := cal.Ranges[key]
		if !ok || r.Max <= r.Min {
			return nil, fmt.Errorf("calibration.json: missing or degenerate range %q", key)
		}
	}

	var m Manifest
	if err := json.Unmarshal(manifestJSON, &m); err != nil {
		return nil, fmt.Errorf("parse manifest.json: %w", err)
	}

	return &Data{
		Words:         words,
		Bigrams:       bigrams,
		Trigrams:      trigrams,
		WordRange:     cal.Ranges["slop_words"],
		TrigramRange:  cal.Ranges["slop_trigrams"],
		ContrastRange: cal.Ranges["contrast_patterns"],
		Manifest:      m,
	}, nil
}
